/** Get translated scenario group label */
export function uiGroupLabel(speakLang: string, groupIdx: number, fallback: string): string {
  return UI_SCENARIO_GROUPS[speakLang]?.[groupIdx] ?? fallback;
}

/** Get translated phrase label */
export function uiPhraseLabel(speakLang: string, key: string, fallback: string): string {
  return UI_PHRASE_LABELS[speakLang]?.[key] ?? fallback;
}

export const NEEDS_ROM: Record<string, boolean> = {
  ja: true, zh: true, ko: true, ar: true, hi: true, ru: true, th: true, bg: true
};

/** All languages benefit from phonetic guides */
export function needsPhon(_lang: string): boolean {
  return true;
}

export function needsRom(lang: string): boolean {
  return !!NEEDS_ROM[lang];
}

