// ── Helper: get phrase in target language ──

export function langPhrase(lang: string, key: PhraseKey): string {
  return TR[lang]?.[key] ?? "[GREETING]";
}

export function langRom(lang: string, key: PhraseKey): string {
  return TR_ROM[lang]?.[key] ?? "";
}

/** Get phonetic pronunciation template for a phrase key */
export function langPhon(lang: string, key: PhraseKey): string {
  return TR_PHON[lang]?.[key] ?? "";
}

// ── Helper: get language display for glasses list ──

export function getLangListItems(): string[] {
  return LANG_CODES.map(code => `${LANG_FLAG[code]} ${LANG_LABEL[code]}`);
}
